style.css:
@-moz-document url("https://animego.org") {
#wrap {
  background-image: url("https://sun9-74.userapi.com/impg/gkxIlxHQ75julxCfBLdkZ-_CG8ytNVjlYNcj_g/DBsbS6uVRH4.jpg?size=1920x1080&quality=96&sign=6df6001d21fd48d11f127faa4fe7e075&type=album");
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

::-webkit-scrollbar {
    width: 10px;
  background: black; 
}
/* Handle */
::-webkit-scrollbar-thumb {
    -webkit-border-radius: 10px;
    border-radius: 10px;
    background: rgba(255,0,0,0.8); 
    -webkit-box-shadow: inset 0 0 6px rgba(0,0,0,0.5); 
}

.row {
  padding: 10px !important;
  backdrop-filter: blur(20px);
  border-radius: 15px;
}
.py-3:nth-child(5) .row {
	padding: 25px 5px !important;
}
.py-3:nth-child(6) > .container > .row {
	padding: 25px 5px !important;
}



/* BLOCKS */
.col-lg-4 > .card {
  width: 81em !important;
	 background-color: rgba(0,0,0, 0.1) !important;
  color: white !important;
}
.card > .list-group-item {
  border: none;
	background-color: transparent !important;
  transition: 250ms;
}
.card > .list-group-item:hover {
  transform: scale(1.02);
  margin: 5px 0 !important;
  background-color: rgba(0,0,0, 0.15) !important;
}
.list-group-item .seasons-item-info {
	color: white !important;
}

/*SEASONS CARDS*/
#tns1-item0 {
  transition: 250ms;
}
#tns1-item0:hover {
	margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item1 {
  transition: 250ms;
}
#tns1-item1:hover {
	margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item2 {
  transition: 250ms;
}
#tns1-item2:hover {
	margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item3 {
  transition: 250ms;
}
#tns1-item3:hover {
	margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item4 {
  transition: 250ms;
}
#tns1-item4:hover {
	margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item5 {
  transition: 250ms;
}
#tns1-item5:hover {
  margin: 0 10px;
  transform: scale(1.08);
}
#tns1-item6 {
  transition: 250ms;
}
#tns1-item6:hover {
  padding-right: 20px;
  transform: scale(1.08);
}
#tns1 > .tns-item {
  padding-right: 15px;
}


#content {
	background-color: rgba(0,0,0, 0.1) !important;
  border: none;
}
.col-12 > .animes-list-item {
	width: auto !important;
  transition: 250ms;
}
.col-12 > .animes-list-item:hover {
  margin: 15px 0 !important;
  transform: scale(1.06);
  background-color: rgba(0,0,0, 0.2) !important;
  border-bottom-right-radius: 15px;
  border-top-right-radius: 15px;
  cursor: pointer;
}
.col-12 > .animes-list-item:active {
  transform: scale(1);
  transition: 100ms ease;
}




.col-lg-6:nth-child(1) {
	display: none;
}
.mb-md-0 {
	display: none;
}



/*TEXT COLORS (OTHERS)*/

.nav-item > .text-link-gray {
	color: white;
  transition: 250ms;
}
.nav-item > .text-link-gray:hover {
  transform:  scale(1.06);
}
.text-dark {
	color: white !important;
}
.col-12 > .animes-list-item > .media-body > .mb-2 {
	color: white !important;
}
.col-12 > .animes-list-item .mb-2 {
	color: white !important;
}
.col-12 .anime-year > .text-link-gray {
	color: white !important;
}
.col-12 span > .text-link-gray {
	color: white !important;
}


/* FILTER */

#filter {
  background-color: rgba(0,0,0, 0.4) !important;
  color: white !important;
}

.bg-white {
	background-color: transparent !important;
}
.type .btn-filter {
	background-color: transparent !important;
   color: white !important;
}
.genres .btn-filter {
	background-color: transparent !important;
   color: white !important;
}
.dubbings .btn-filter {
	background-color: transparent !important;
   color: white !important;
}
.status .btn-filter {
	background-color: transparent !important;
   color: white !important;
}
.rating .btn-filter {
	background-color: transparent !important;
   color: white !important;
}
.noUi-handle-lower > .noUi-tooltip {
	background-color: transparent !important;
}
.noUi-handle-upper > .noUi-tooltip {
	background-color: transparent !important;
}
.btn-lg {
	background-color: transparent !important;
}
.btn-lg:hover {
  background-color: rgba(14, 55, 21, 0.3) !important;
}
.show > .dropdown-menu {
	background-color: rgba(0,0,0, 0.5);
  border: 2px solid black;
  backdrop-filter: blur(20px);
}
.label > .custom-control {
	color: white;
}
.label {
  border-bottom: 2px solid gray;
	transition: 250ms;
}
.label:hover {
  background-color: rgba(14, 55, 21, 0.4);
}
.show > .dropdown-item > .custom-control {
	color: white;
}
.form-group .dropdown-item > .custom-control {
	color: white !important;
}
.show > .dropdown-item > .custom-control {
	color: white !important;
}
.show > .dropdown-item {
  transition: 250ms;
}
.show > .dropdown-item:hover {
	background-color: rgba(14, 55, 21, 0.4);
}
.show .dropdown-item {
	transition: 250ms;
}
.show .dropdown-item:hover {
  background-color: rgba(14, 55, 21, 0.4);
}

div {
  transition: 200ms;
}

/*FOOTER, HEADER*/

#footer > .navbar-dark {
	background-color: transparent !important;
  backdrop-filter: blur(20px);
}
.mb-4, .my-4 {
  margin: 0 !important;
}
header {
  background-color: black;
}


/*OTHER*/


.mr-2 {
  color: white;
}


#sorter-sort {
	background-color: transparent;
  color: white;
}
.sortable {
	color: white;
}


.read-more-container[data-read-more-init=true]::after {
  content: none;
}


.col-6 {
	color: white;
}
.font-weight-normal {
	color: white;
}
.col-12 > .b-tooltipped {
	color: white;
}
div > span > .text-link-gray > span {
	color: white;
}


.content {
	background-color: transparent;
}
.col-12 > .released-episodes-item .col-5 {
	color: white;
}
.col-12 .col-3 > span {
	color: white;
}
.col-12 .col-6 span {
	color: white;
}
.read-more-text {
	color: white;
}
.bg-dark {
	background-color: rgba(0,0,0, 0.1) !important;
  border-radius: 15px;
}
.col-12 > .released-episodes-item:hover {
	background-color: rgba(0,0,0, 0.1);
}
.border-primary {
	backdrop-filter: blur(15px);
}
div {
  color: white !important;
}
.border-primary {
	background-color: black !important;
}


.nav-item > .text-link-gray {
	gap: 0;
  margin-right: 20px;
  padding: 5px 0;
}
.ml-2 > .nav-item > .nav-link {
	padding: 10px 0;
  margin-right: 30px;
}
}
